// =============================================================
// CONFIGURAÇÃO MESTRE — BioSorriso
// =============================================================

const body = $input.item.json.body || $input.item.json;

const idAtendimento = body.id_atendimento || body.atendimento_id || body.session_id || body.sessionId || '';

// ── Dados do paciente ─────────────────────────────────────────
const telefoneRaw        = body.telefone_cliente || body.telefone_contato || body.telefone || '';
const telefoneLimpo      = telefoneRaw.toString().replace(/\D/g, '');
const nomePaciente       = body.nome_cliente || body.nome_contato || 'Paciente';
const insistiu           = body.insistiu === true || body.insistiu === 'true';
const horarioPreferido   = (body.horario_preferido || '').trim();
const isPeriodo          = /manh[aã]|tarde/i.test(horarioPreferido);
const periodoPreferencia = isPeriodo ? (/tarde/i.test(horarioPreferido) ? 'tarde' : 'manha') : '';

// ── Configuração da unidade ───────────────────────────────────
const TIMEZONE = 'America/Sao_Paulo';

const CONFIG = {
  subscriber_id:             'biosorriso',
  business_id:               '4849617980620800',
  company_id:                '21202640000154',
  nome_unidade:              'BioSorriso',
  nome_empresa:              'BioSorriso',
  link_agenda:               '25551',
  duracao_servico:           30,
  capacidade_simultanea:     1,
  timezone:                  TIMEZONE,
  limite_dias_busca_normal:  7,
  threshold_proximidade_min: 90,
  categoria_cor:             '#2196F3',
  categoria_descricao:       'Avaliação',
  nota_agendamento:          'Agendamento realizado via IA',
  nota_reagendamento:        'Reagendamento realizado via IA',
  nota_novo_paciente:        'Paciente cadastrado via IA',
  // ✅ FIX: ID corrigido para o profissional com mais slots na agenda
  profissional:         { id: '4779727926460416', nome: 'Eduardo dos Santos Menezes Loiola' },
  // ✅ FIX: Fallbacks adicionados para os demais profissionais retornados pela API
  profissional_fallback:  { id: '4779727926460416', nome: 'Dr. Jacyo' },
  profissional_fallback2: { id: '6013144164466688', nome: 'Eduardo dos Santos Menezes Loiola' },
  authorization: 'Basic ' + Buffer.from('biosorriso:8294b9b9-b79d-4a85-b774-11c7bce8c8c3').toString('base64')
};

// ── Datas ─────────────────────────────────────────────────────
const hoje       = DateTime.now().setZone(CONFIG.timezone);
const dataInicio = hoje.toFormat('yyyy-MM-dd');

const dataRaw = body.data_iso || body.data_inicio || body.data_agendada || '';
let dtP = null;

if (dataRaw) {
  dtP = DateTime.fromISO(dataRaw, { zone: CONFIG.timezone });
  if (!dtP.isValid) dtP = DateTime.fromFormat(dataRaw, 'yyyy-MM-dd HH:mm', { zone: CONFIG.timezone });
  if (!dtP.isValid) dtP = DateTime.fromFormat(dataRaw, 'dd/MM/yyyy HH:mm', { zone: CONFIG.timezone });
}

const horaDoISO = (dtP && dtP.isValid && (dtP.hour > 0 || dtP.minute > 0))
  ? dtP.toFormat('HH:mm') : '';

const horaEspecifica = !isPeriodo && horarioPreferido.includes(':') ? horarioPreferido : '';
const horaFinal = horaEspecifica
  || ((body.horario_agendado && body.horario_agendado.length >= 4) ? body.horario_agendado : '')
  || ((body.horario && body.horario.length >= 4) ? body.horario : '')
  || horaDoISO;

const dataFinal = (dtP && dtP.isValid) ? dtP.toFormat('yyyy-MM-dd') : '';
const dataFim   = (dtP && dtP.isValid)
  ? dtP.plus({ days: 7 }).toFormat('yyyy-MM-dd')
  : hoje.plus({ days: 7 }).toFormat('yyyy-MM-dd');

const spin = body.SPIN || body.spin || null;

return {
  json: {
    acao_fluxo:          body.action || body.acao_fluxo,
    id_atendimento:      idAtendimento,
    helena_company_id:   '94732f06-3633-4d01-a32e-080fe0fbcbc3',
    nome_paciente:       nomePaciente,
    telefone_limpo:      telefoneLimpo,
    insistiu:            insistiu,
    data_nascimento:     body.data_nascimento || '',
    data_inicio:         dataInicio,
    data_agendada:       dataFinal,
    data_antiga:         body.data_antiga || body['data-antiga'] || '',
    data_fim:            dataFim,
    horario_agendado:    horaFinal,
    horario_preferido:   horarioPreferido,
    periodo_preferencia: periodoPreferencia,
    spin:                spin,
    config_agenda: {
      subscriber_id:             CONFIG.subscriber_id,
      business_id:               CONFIG.business_id,
      company_id:                CONFIG.company_id,
      nome_unidade:              CONFIG.nome_unidade,
      nome_empresa:              CONFIG.nome_empresa,
      link_agenda:               CONFIG.link_agenda,
      duracao_servico:           CONFIG.duracao_servico,
      capacidade_simultanea:     CONFIG.capacidade_simultanea,
      timezone:                  CONFIG.timezone,
      limite_dias_busca_normal:  CONFIG.limite_dias_busca_normal,
      threshold_proximidade_min: CONFIG.threshold_proximidade_min,
      categoria_cor:             CONFIG.categoria_cor,
      categoria_descricao:       CONFIG.categoria_descricao,
      nota_agendamento:          CONFIG.nota_agendamento,
      nota_reagendamento:        CONFIG.nota_reagendamento,
      nota_novo_paciente:        CONFIG.nota_novo_paciente,
      profissional:              CONFIG.profissional,
      profissional_fallback:     CONFIG.profissional_fallback,
      profissional_fallback2:    CONFIG.profissional_fallback2,
      authorization:             CONFIG.authorization
    }
  }
};

// =============================================================
// LÓGICA INTELIGENTE — BioSorriso
//
// REGRA DE PRIORIDADE:
//   1. DIA é prioridade SE houver slot dentro do threshold de
//      proximidade do horário pedido (padrão: 90min).
//   2. Se o dia pedido tem slots mas nenhum dentro do threshold,
//      busca outros dias com horário mais próximo do pedido.
//   3. Se o dia pedido não tem slot algum, busca outros dias
//      ordenados por proximidade do horário pedido.
//
// RESILIÊNCIA DE IDs:
//   Se nenhum slot bater com os IDs configurados, aceita todos
//   os slots disponíveis da API (evita agenda vazia por ID errado).
// =============================================================

const cfgNode = $('Configuracao Unidades').first().json;
const ca      = cfgNode.config_agenda || {};

const TIMEZONE      = ca.timezone || 'America/Sao_Paulo';
const LIMITE_DIAS   = ca.limite_dias_busca_normal || 7;
const THRESHOLD_MIN = ca.threshold_proximidade_min || 90;

const PROF_PRINCIPAL  = { id: String(ca.profissional?.id || ''),           nome: ca.profissional?.nome || 'Profissional' };
const PROF_FALLBACK   = { id: String(ca.profissional_fallback?.id || ''),  nome: ca.profissional_fallback?.nome || '' };
const PROF_FALLBACK2  = { id: String(ca.profissional_fallback2?.id || ''), nome: ca.profissional_fallback2?.nome || '' };

const IDS_CONFIGURADOS = new Set(
  [PROF_PRINCIPAL.id, PROF_FALLBACK.id, PROF_FALLBACK2.id].filter(Boolean)
);

const diasAPI  = $input.all().map(i => i.json);
const insistiu = cfgNode.insistiu === true;
const hRaw     = cfgNode.horario_agendado || '';
const dRaw     = cfgNode.data_agendada || '';
const periodoPreferencia = cfgNode.periodo_preferencia || '';
const agora    = DateTime.now().setZone(TIMEZONE);

function horaParaMin(str) {
  if (!str) return -1;
  const p = str.split(':');
  return parseInt(p[0]) * 60 + parseInt(p[1] || '0');
}

function fmtBloco(b) {
  const [, mm, dd] = b.data.split('-');
  return `\uD83D\uDDD3\uFE0F *${dd}/${mm} (${b.semana})* às *${b.horario}* – *${b.horario_fim}* com ${b.profNome}`;
}

function topNPorProximidade(blocos, minAlvo, n = 3) {
  if (!blocos.length) return [];
  const copia = blocos.slice();
  if (minAlvo < 0) {
    copia.sort((a, b) => a.minutos - b.minutos);
  } else {
    copia.sort((a, b) =>
      Math.abs(a.minutos - minAlvo) - Math.abs(b.minutos - minAlvo)
      || a.minutos - b.minutos
    );
  }
  const vistos = new Set();
  return copia
    .filter(b => {
      const chave = `${b.data}_${b.horario}`;
      if (vistos.has(chave)) return false;
      vistos.add(chave);
      return true;
    })
    .slice(0, n);
}

function topNDiasComMelhorHorario(blocos, dataRef, minAlvo, n = 3) {
  const porDia = {};
  for (const b of blocos) {
    const atual = porDia[b.data];
    if (!atual) {
      porDia[b.data] = b;
    } else if (minAlvo >= 0
               && Math.abs(b.minutos - minAlvo) < Math.abs(atual.minutos - minAlvo)) {
      porDia[b.data] = b;
    }
  }
  const dias = Object.keys(porDia).sort();
  const pool = dataRef ? dias.filter(d => d >= dataRef) : dias;
  const escolhidos = pool.length >= n ? pool : dias;
  return escolhidos.slice(0, n).map(d => porDia[d]);
}

function resolverProfissional(sid) {
  if (sid === PROF_PRINCIPAL.id)  return { profId: PROF_PRINCIPAL.id,  profNome: PROF_PRINCIPAL.nome };
  if (sid === PROF_FALLBACK.id  && PROF_FALLBACK.id)  return { profId: PROF_FALLBACK.id,  profNome: PROF_FALLBACK.nome };
  if (sid === PROF_FALLBACK2.id && PROF_FALLBACK2.id) return { profId: PROF_FALLBACK2.id, profNome: PROF_FALLBACK2.nome };
  return null;
}

function processarDia(dia) {
  const slots    = (dia.AvaliableTimes || []).filter(s => s.isSelectable !== false);
  const principal = [];
  const fallback  = [];
  const outros    = [];

  for (const slot of slots) {
    const sid = String(slot.professionalId);
    const bloco = {
      data:        dia.jsonDate,
      semana:      dia.Week,
      minutos:     horaParaMin(slot.from),
      horario:     slot.from,
      horario_fim: slot.to
    };

    const prof = resolverProfissional(sid);
    if (prof) {
      const entry = { ...bloco, ...prof };
      if (sid === PROF_PRINCIPAL.id) principal.push(entry);
      else fallback.push(entry);
    } else {
      outros.push({ ...bloco, profId: sid, profNome: 'Profissional' });
    }
  }
  return { principal, fallback, outros };
}

let blocosPrincipal = [];
let blocosFallback  = [];
let blocosOutros    = [];

for (const dia of diasAPI) {
  const { principal, fallback, outros } = processarDia(dia);
  blocosPrincipal = blocosPrincipal.concat(principal);
  blocosFallback  = blocosFallback.concat(fallback);
  blocosOutros    = blocosOutros.concat(outros);
}

const temBlocosConhecidos = blocosPrincipal.length > 0 || blocosFallback.length > 0;
const todosBlocos = temBlocosConhecidos
  ? blocosPrincipal.concat(blocosFallback)
  : blocosOutros;

const usandoFallback    = blocosPrincipal.length === 0 && blocosFallback.length > 0;
const usandoModoAberto  = !temBlocosConhecidos && blocosOutros.length > 0;

let dtSolicitado = null;
if (dRaw && hRaw) {
  dtSolicitado = DateTime.fromFormat(`${dRaw} ${hRaw}`, 'yyyy-MM-dd HH:mm', { zone: TIMEZONE });
}

const dataAlvo      = dtSolicitado?.isValid ? dtSolicitado.toFormat('yyyy-MM-dd') : (dRaw || null);
const minSolicitado = (hRaw && hRaw !== '00:00') ? horaParaMin(hRaw) : -1;

const dtLabel = dtSolicitado?.isValid
  ? dtSolicitado.setLocale('pt-BR').toFormat('dd/MM (cccc)')
  : (dRaw || 'data solicitada');

let diffDias = 0, bloqueado = false;
if (dtSolicitado?.isValid) {
  diffDias = dtSolicitado.startOf('day').diff(agora.startOf('day'), 'days').days;
  if (diffDias > LIMITE_DIAS && !insistiu) bloqueado = true;
}

let resultado, exactMatch = false;
const sugestoesHorarios = [];

if (periodoPreferencia) {
  const faixas = {
    manha: { inicio: 8*60,     fim: 12*60   },
    tarde: { inicio: 13*60+30, fim: 18*60+1 }
  };
  const faixa        = faixas[periodoPreferencia] || faixas.manha;
  const labelPeriodo = periodoPreferencia === 'manha' ? 'manhã' : 'tarde';
  const labelOutro   = periodoPreferencia === 'manha' ? 'tarde' : 'manhã';
  const dataMinima   = dataAlvo || agora.toFormat('yyyy-MM-dd');

  const blocosPeriodo = todosBlocos
    .filter(b => b.minutos >= faixa.inicio && b.minutos < faixa.fim && b.data >= dataMinima)
    .sort((a, b) => a.data.localeCompare(b.data) || a.minutos - b.minutos);

  if (blocosPeriodo.length === 0) {
    resultado = `😕 Não há horários disponíveis no período da *${labelPeriodo}* para *${dtLabel}*.\n\nTemos opções no período da *${labelOutro}*. Prefere que eu verifique?`;
  } else {
    const primeiro = blocosPeriodo[0];
    sugestoesHorarios.push(`${primeiro.data} ${primeiro.horario}`);
    const blocosMesmoDia  = blocosPeriodo.filter(b => b.data === primeiro.data);
    const segundoMesmoDia = blocosMesmoDia.find(b => b.minutos - primeiro.minutos >= 120);
    const segundo         = segundoMesmoDia || blocosPeriodo.find(b => b.data > primeiro.data);
    if (segundo) {
      sugestoesHorarios.push(`${segundo.data} ${segundo.horario}`);
      resultado = `📅 Encontrei dois horários disponíveis no período da *${labelPeriodo}*:\n\n${fmtBloco(primeiro)}\n${fmtBloco(segundo)}\n\nQual desses fica melhor para você?`;
    } else {
      resultado = `📅 Encontrei o seguinte horário no período da *${labelPeriodo}*:\n\n${fmtBloco(primeiro)}\n\nEsse horário funciona para você?`;
    }
  }
}
else if (bloqueado) {
  const limiteData         = agora.startOf('day').plus({ days: LIMITE_DIAS }).toFormat('yyyy-MM-dd');
  const blocosDentroLimite = todosBlocos.filter(b => b.data <= limiteData);
  const proximos           = topNDiasComMelhorHorario(
    blocosDentroLimite,
    agora.toFormat('yyyy-MM-dd'),
    minSolicitado,
    3
  );

  if (proximos.length === 0) {
    resultado = `\uD83D\uDE15 Não há horários disponíveis nos próximos ${LIMITE_DIAS} dias.\n\nPosso verificar outra data?`;
  } else {
    proximos.forEach(b => sugestoesHorarios.push(`${b.data} ${b.horario}`));
    resultado =
      `\u26A0\uFE0F A data que você pediu (*${dtLabel}*) está a *${Math.ceil(diffDias)} dias* de hoje.\n\n` +
      `Para garantir um atendimento mais rápido, separei os horários disponíveis mais próximos:\n\n` +
      proximos.map(fmtBloco).join('\n');
  }
}
else {
  const blocosDoDia = dataAlvo
    ? todosBlocos.filter(b => b.data === dataAlvo)
    : [];

  const melhorDoDia = blocosDoDia.length > 0
    ? topNPorProximidade(blocosDoDia, minSolicitado, 1)[0]
    : null;

  const distanciaMelhor = (melhorDoDia && minSolicitado >= 0)
    ? Math.abs(melhorDoDia.minutos - minSolicitado)
    : 0;

  const diaTemSlotProximo = melhorDoDia !== null
    && (minSolicitado < 0 || distanciaMelhor <= THRESHOLD_MIN);

  if (diaTemSlotProximo) {
    const exato = minSolicitado >= 0
      ? blocosDoDia.find(b => b.minutos === minSolicitado)
      : null;

    if (exato) {
      exactMatch = true;
      sugestoesHorarios.push(`${exato.data} ${exato.horario}`);
      resultado =
        `\u2705 Ótima notícia! O horário *${dtLabel} às ${exato.horario}* está disponível ` +
        `com *${exato.profNome}*.\n\nPosso confirmar sua avaliação?`;
    } else {
      const opcoes = topNPorProximidade(blocosDoDia, minSolicitado, 3);
      opcoes.forEach(b => sugestoesHorarios.push(`${b.data} ${b.horario}`));
      const intro = minSolicitado >= 0
        ? `Não temos exatamente às *${hRaw}* em *${dtLabel}*, mas tenho estas opções no mesmo dia:`
        : `Encontrei os seguintes horários disponíveis em *${dtLabel}*:`;
      resultado =
        `\uD83D\uDCC5 ${intro}\n\n` +
        opcoes.map(fmtBloco).join('\n') +
        `\n\nQual desses fica melhor para você?`;
    }
  }
  else {
    const dataRef = dataAlvo || agora.toFormat('yyyy-MM-dd');
    const hoje    = agora.toFormat('yyyy-MM-dd');

    const proximos = topNDiasComMelhorHorario(
      todosBlocos.filter(b => b.data >= hoje),
      dataRef,
      minSolicitado,
      3
    );

    if (proximos.length === 0) {
      resultado = dataAlvo
        ? `\uD83D\uDE15 Não há horários disponíveis em *${dtLabel}* nem nos dias seguintes. Posso verificar outras datas?`
        : `\uD83D\uDE15 Não há horários disponíveis no período consultado. Posso verificar outras datas?`;
    } else {
      proximos.forEach(b => sugestoesHorarios.push(`${b.data} ${b.horario}`));
      const intro = blocosDoDia.length > 0
        ? `Não temos um horário próximo de *${hRaw}* em *${dtLabel}*, mas encontrei estas opções nos dias mais próximos:`
        : dataAlvo
          ? `Não há horários em *${dtLabel}*, mas encontrei estas opções nos dias mais próximos:`
          : `Encontrei estas opções nos dias mais próximos:`;
      resultado =
        `\uD83D\uDCC5 ${intro}\n\n` +
        proximos.map(fmtBloco).join('\n') +
        `\n\nQual desses fica melhor para você?`;
    }
  }
}

return {
  json: {
    resultado,
    sugestoes_horarios:      sugestoesHorarios,
    data_distante_bloqueada: bloqueado,
    exact_match:             exactMatch,
    diff_dias:               Math.ceil(diffDias),
    total_dias_api:          diasAPI.length,
    total_blocos_validos:    todosBlocos.length,
    usando_fallback:         usandoFallback,
    usando_modo_aberto:      usandoModoAberto
  }
};

// ── Validar Slot Agendar ─────────────────────────────────────────────
let d = {};
try { d = $('Configuracao Unidades').first().json; } catch(e) { d = $input.item.json; }

const PROF_PRINCIPAL = { id: String(d.config_agenda?.profissional?.id || ''),          nome: d.config_agenda?.profissional?.nome || 'Profissional' };
const PROF_FALLBACK  = { id: String(d.config_agenda?.profissional_fallback?.id || ''), nome: d.config_agenda?.profissional_fallback?.nome || '' };

const inputItems    = $input.all().map(i => i.json);
const isNovoFormato = inputItems.length > 0 && Array.isArray(inputItems[0].AvaliableTimes);

let slots = [];
if (isNovoFormato) {
  slots = (inputItems[0].AvaliableTimes || []).filter(s => s.isSelectable !== false);
} else {
  slots = inputItems;
}

const norm = h => {
  if (!h) return '';
  const p = h.toString().split(':');
  return p[0].padStart(2,'0') + ':' + (p[1]||'00').padStart(2,'0');
};

const hAlvo = norm(d.horario_agendado || '');

function buscarSlot(profId) {
  return slots.find(s => {
    const id   = String(isNovoFormato ? s.professionalId : s.ProfessionalId);
    const from = norm(isNovoFormato ? s.from : s.From);
    return id === profId && from === hAlvo;
  }) || null;
}

let v = { aprovado: false, motivo: 'Horário indisponível.' };
let idF = null, nomeF = '';

if (!slots.length) {
  v.motivo = 'Não há agenda aberta ou horários disponíveis neste dia.';
} else if (!hAlvo) {
  v.motivo = 'Horário solicitado não informado.';
} else {
  let slotEncontrado = buscarSlot(PROF_PRINCIPAL.id);
  if (slotEncontrado) {
    v = { aprovado: true, motivo: 'Horário disponível.' };
    idF = PROF_PRINCIPAL.id; nomeF = PROF_PRINCIPAL.nome;
  } else if (PROF_FALLBACK.id) {
    slotEncontrado = buscarSlot(PROF_FALLBACK.id);
    if (slotEncontrado) {
      v = { aprovado: true, motivo: 'Horário disponível.' };
      idF = PROF_FALLBACK.id; nomeF = PROF_FALLBACK.nome;
    }
  }
  if (!v.aprovado) {
    v.motivo = `O horário ${d.horario_agendado} não está disponível.`;
  }
}

return {
  json: {
    ...d,
    validacao:               v,
    id_profissional_final:   idF,
    nome_profissional_final: nomeF,
    hora_buscada:            hAlvo,
    slots_encontrados_total: slots.length
  }
};

